// Bucles
//=====================================================================================================================
//--- cada 30 s: zonas nuevas, perdidas
VIOC_MERC_fnc_zonesTick = {
	VIOC_MERC_SIDES = call VIOC_MERC_fnc_sides;
	//--- perdidas
	{
		private _z = _x;
		//--- (revision M1) tambien si el bando ya no es uno de los que sirven (mision A: el jugador cambio de bando)
		if ((_z get "state") in ["dormant", "active", "done"] && {!([_z] call VIOC_MERC_fnc_valid) || {((_z get "kind") != "test") && {!((_z get "side") in VIOC_MERC_SIDES)}}}) then {
			_z set ["state", "lost"];
			_z set ["lostAt", time];
			VIOC_MERC_CD set [_z get "id", (VIOC_MERC_CD getOrDefault [_z get "id", 0]) max (time + VIOC_MERC_LOST_CD)];
			[6] call VIOC_MERC_fnc_stat;
			[format ["%1: zona perdida (%2)", _z get "name", _z get "kind"]] call VIOC_MERC_fnc_log;
			private _ret = [_z] call VIOC_MERC_fnc_retreatPos;
			{
				_x enableAI "PATH";
				_x setUnitPos "AUTO";
				_x doMove _ret;
			} forEach (([_z] call VIOC_MERC_fnc_units) select {isNull objectParent _x});
		};
	} forEach VIOC_MERC_ZONES;
	//--- nuevas
	{
		private _side = _x;
		{
			_x params ["_id", "_kind", "_name", "_town", "_anchor"];
			private _n = {((_x get "state") != "gone") && {(_x get "kind") != "test"}} count VIOC_MERC_ZONES;	//--- tambien las que se retiran
			if (_n < VIOC_MERC_MAX_ZONES
				&& {(VIOC_MERC_ZONES findIf {(_x get "id") isEqualTo _id && {(_x get "state") != "gone"}}) < 0}
				&& {(VIOC_MERC_CD getOrDefault [_id, 0]) <= time}
				&& {(VIOC_MERC_ZONES findIf {((_x get "state") in ["dormant", "active", "done"]) && {((_x get "anchor") distance2D _anchor) < VIOC_MERC_SEP}}) < 0}) then {
				[_side, _id, _kind, _name, _town, _anchor] call VIOC_MERC_fnc_newZone;
			};
		} forEach ([_side] call VIOC_MERC_fnc_candidates);
	} forEach VIOC_MERC_SIDES;
	VIOC_MERC_ZONES = VIOC_MERC_ZONES select {(_x get "state") != "gone"};
};

//--- [bando, id, tipo, nombre, pueblo, ancla] -> zona (contrato nuevo, todavia sin unidades)
VIOC_MERC_fnc_newZone = {
	params ["_side", "_id", "_kind", "_name", "_town", "_anchor"];
	private _z = createHashMapFromArray [
		["id", _id], ["kind", _kind], ["name", _name], ["side", _side], ["sid", (_side) call CTI_CO_FNC_GetSideID], ["town", _town],
		["anchor", _anchor], ["state", "dormant"], ["lair", []], ["groups", []], ["vobjs", []], ["boss", objNull], ["gEsc", grpNull],
		["t0", time], ["farSince", -1], ["relocAt", 0], ["moveEnd", -1], ["bossAt", []], ["lairTry", 0], ["noRoomLog", 0]
	];
	([_z] call VIOC_MERC_fnc_newRoster) params ["_roles", "_vehs"];
	_z set ["roster", _roles];
	_z set ["vehs", _vehs apply {[_x select 0, _x select 1, [], -1, _x select 1]}];
	VIOC_MERC_ZONES pushBack _z;
	[0] call VIOC_MERC_fnc_stat;
	private _sn = [_side] call VIOC_MERC_fnc_sideName;
	private _txt = switch (_kind) do {
		case "hq": {format ["Inteligencia: %1 contrato mercenarios de ION para proteger a un jefe cerca de su cuartel general.", _sn]};
		case "capital": {format ["Inteligencia: mercenarios de ION protegen a un jefe de %1 en %2 (la capital).", _sn, _name]};
		case "airfield": {format ["Inteligencia: mercenarios de ION protegen a un jefe de %1 en el aerodromo de %2.", _sn, _name]};
		default {format ["Inteligencia: mercenarios de ION protegen a un jefe de %1 cerca de %2.", _sn, _name]};
	};
	{ [_txt, _x] call VIOC_MERC_fnc_say } forEach ((call VIOC_MERC_fnc_allPlayers) select {(side (group _x)) in [west, east, resistance] && {(side (group _x)) != _side}});
	[format ["contrato nuevo: %1 (%2) para %3, %4 hombres, vehiculos %5", _name, _kind, _side, count _roles, _vehs apply {_x select 0}]] call VIOC_MERC_fnc_log;
	_z
};

//--- [zona] -> posicion de retirada: el pueblo del bando mas cercano a 0.6-5 km o 1.5 km lejos del jugador enemigo mas cercano
VIOC_MERC_fnc_retreatPos = {
	params ["_z"];
	private _c = if ((_z get "lair") isNotEqualTo []) then {(_z get "lair") select 0} else {_z get "anchor"};
	private _best = [];
	private _bd = 5000;
	{
		private _d = _x distance2D _c;
		if ((_x getVariable ["cti_town_sideID", -1]) == (_z get "sid") && {_d > 600} && {_d < _bd}) then {_bd = _d; _best = getPosATL _x};
	} forEach CTI_Towns;
	if (_best isNotEqualTo []) exitWith {_best call VIOC_MERC_fnc_p0};
	private _pls = [_z get "side"] call VIOC_MERC_fnc_enemyPlayers;
	private _dir = random 360;
	if (_pls isNotEqualTo []) then {
		private _n = _pls select 0;
		{ if ((_x distance2D _c) < (_n distance2D _c)) then {_n = _x} } forEach _pls;
		_dir = (_n getDir _c);
	};
	(_c getPos [1500, _dir]) call VIOC_MERC_fnc_p0
};

//--- [zona]: cada 10 s
VIOC_MERC_fnc_zoneTick = {
	params ["_z"];
	private _state = _z get "state";
	private _side = _z get "side";
	private _pls = [_side] call VIOC_MERC_fnc_enemyPlayers;
	private _ref = if ((_z get "lair") isNotEqualTo []) then {(_z get "lair") select 0} else {_z get "anchor"};
	switch (_state) do {
		case "dormant": {
			if ((_pls findIf {(_x distance2D _ref) < VIOC_MERC_SPAWN_R}) < 0) exitWith {};
			if ((_z get "lair") isEqualTo []) then {
				if ((_z get "lairTry") > time) exitWith {};
				private _l = [_z] call VIOC_MERC_fnc_lair;
				if (_l isEqualTo []) then {_z set ["lairTry", time + 120]; [format ["%1: sin escondite para el jefe (reintento en 2 min)", _z get "name"]] call VIOC_MERC_fnc_log} else {_z set ["lair", _l]};
			};
			if ((_z get "lair") isEqualTo []) exitWith {};
			private _bp = (_z get "lair") select 0;
			if ((_pls findIf {(_x distance2D _bp) < VIOC_MERC_NOSPAWN_R}) >= 0) exitWith {};
			if ([_bp, 700, _pls] call VIOC_MERC_fnc_seen) exitWith {};
			//--- presupuesto: si no cabe, menos tiradores, sin el segundo vehiculo artillado, hasta VIOC_MERC_MIN_MEN
			private _need = [_z] call VIOC_MERC_fnc_need;
			private _cut = 0;
			while {!([_need] call VIOC_MERC_fnc_room) && {_need > VIOC_MERC_MIN_MEN} && {_cut < 12}} do {
				_cut = _cut + 1;
				private _ro = _z get "roster";
				private _vs = _z get "vehs";
				private _ia = _vs findIf {(_x select 1) && {_x select 4}};
				switch (true) do {
					case ("rifle" in _ro): {_ro deleteAt (_ro find "rifle")};
					case ((({(_x select 1) && {_x select 4}} count _vs) > 1) && {_ia >= 0}): {_vs deleteAt _ia};
					case ("lat" in _ro): {_ro deleteAt (_ro find "lat")};
					default {_cut = 99};
				};
				_need = [_z] call VIOC_MERC_fnc_need;
			};
			if !([_need] call VIOC_MERC_fnc_room) exitWith {
				[7] call VIOC_MERC_fnc_stat;
				if ((_z get "noRoomLog") < time) then {_z set ["noRoomLog", time + 300]; [format ["%1: sin presupuesto de IA para %2 hombres (se espera)", _z get "name", _need]] call VIOC_MERC_fnc_log};
			};
			[_need] call VIOC_MERC_fnc_reserve;
			[_z] call VIOC_MERC_fnc_spawn;
		};
		case "active": {
			private _all = [_z] call VIOC_MERC_fnc_units;
			if (_all isEqualTo []) exitWith {_z set ["state", "gone"]; VIOC_MERC_CD set [_z get "id", time + VIOC_MERC_COOLDOWN]};
			//--- guardar en memoria si no hay jugadores enemigos cerca
			if ((_pls findIf {(_x distance2D _ref) < VIOC_MERC_DESPAWN_R}) < 0 && {(_all findIf {[_x, 1200, _pls] call VIOC_MERC_fnc_seen}) < 0}) then {
				if ((_z get "farSince") < 0) then {_z set ["farSince", time]};
			} else {_z set ["farSince", -1]};
			if ((_z get "farSince") >= 0 && {(time - (_z get "farSince")) > VIOC_MERC_DESPAWN_T}) exitWith {
				[_z, true] call VIOC_MERC_fnc_despawn;
				_z set ["state", "dormant"];
				[2] call VIOC_MERC_fnc_stat;
				[format ["%1: sin jugadores cerca, se guardan %2 hombres y %3 vehiculos", _z get "name", count (_z get "roster"), count (_z get "vehs")]] call VIOC_MERC_fnc_log;
			};
			[_z, _all] call VIOC_MERC_fnc_guard;
		};
		case "done": {
			private _all = [_z] call VIOC_MERC_fnc_units;
			if (_all isNotEqualTo []) then {[_z, _all] call VIOC_MERC_fnc_guard};
			if (_all isEqualTo [] || {((_all + (_z get "vobjs")) findIf {!([_x, 1500] call VIOC_MERC_fnc_canDel)}) < 0}) then {
				[_z, false] call VIOC_MERC_fnc_despawn;
				_z set ["state", "gone"];
				[format ["%1: contrato terminado (jefe muerto), escolta borrada", _z get "name"]] call VIOC_MERC_fnc_log;
			};
		};
		case "lost": {
			private _all = [_z] call VIOC_MERC_fnc_units;
			private _old = (time - (_z getOrDefault ["lostAt", time])) > VIOC_MERC_RETIRE_T;
			{
				if ([_x, 800] call VIOC_MERC_fnc_canDel || {_old && {!([_x, 300] call VIOC_MERC_fnc_nearPlayer)}}) then {
					if (isNull objectParent _x) then {deleteVehicle _x} else {(objectParent _x) deleteVehicleCrew _x};
				};
			} forEach (_all select {isNull objectParent _x || {!((objectParent _x) in (_z get "vobjs"))}});	//--- (revision B2) tambien en vehiculos ajenos
			{
				private _v = _x;
				if (!isNull _v && {((crew _v) findIf {isPlayer _x}) < 0} && {[_v, 800] call VIOC_MERC_fnc_canDel || {_old && {!([_v, 300] call VIOC_MERC_fnc_nearPlayer)}}}) then {
					{ _v deleteVehicleCrew _x } forEach (crew _v);
					deleteVehicle _v;
				};
			} forEach ((_z get "vobjs") select {!isNull _x && {(_x getVariable ["vioc_merc", ""]) isEqualTo (_z get "id")}});
			_z set ["vobjs", (_z get "vobjs") select {!isNull _x}];
			if (([_z] call VIOC_MERC_fnc_units) isEqualTo [] && {(_z get "vobjs") isEqualTo []}) then {
				[_z, false] call VIOC_MERC_fnc_despawn;
				_z set ["state", "gone"];
				[format ["%1: zona perdida, escolta borrada", _z get "name"]] call VIOC_MERC_fnc_log;
			};
		};
		default {};
	};
};

//--- [zona, unidades vivas]: correa de la escolta, el jefe que cambia de lugar, conocimiento compartido, vehiculos tomados
VIOC_MERC_fnc_guard = {
	params ["_z", "_all"];
	private _b = _z get "boss";
	private _bossOk = !isNull _b && {alive _b};
	private _c = if (_bossOk) then {getPosATL _b} else {(_z get "lair") select 0};
	//--- conocimiento compartido (jefe <-> jefe de la escolta <-> artilleros)
	private _ge = _z get "gEsc";
	private _l = if (isNull _ge) then {objNull} else {leader _ge};
	private _seenBy = [];
	{ if (alive _x) then {_seenBy append ((_x targets [true, 700]) select [0, 12])} } forEach ([_b, _l] select {!isNull _x});
	_seenBy = _seenBy arrayIntersect _seenBy;
	if (_seenBy isNotEqualTo []) then {
		{
			private _g = _x;
			if (!isNull _g && {(count units _g) > 0}) then {
				{ _g reveal [_x, 2.5] } forEach _seenBy;
			};
		} forEach (_z get "groups");
	};
	private _danger = _seenBy findIf {alive _x && {(_x distance2D _c) < 500}} >= 0;
	//--- correa: nadie a mas de VIOC_MERC_LEASH m del jefe; sin peligro, de vuelta a su puesto
	{
		private _u = _x;
		if (isNull objectParent _u && {!(_u getVariable ["vioc_merc_boss", false])}) then {
			private _post = _u getVariable ["vioc_merc_post", []];
			if (_post isEqualTo []) then {_post = _c call VIOC_MERC_fnc_p0};
			private _dB = _u distance2D _c;
			private _dP = _u distance2D _post;
			private _ret = _u getVariable ["vioc_merc_ret", -1];
			if (_dB > VIOC_MERC_LEASH || {!_danger && {_dP > 25} && {_ret < 0}}) then {
				_u enableAI "PATH";
				_u doMove _post;
				_u setVariable ["vioc_merc_ret", time];
			} else {
				if (_ret >= 0 && {_dP < 4 || {(time - _ret) > 120}}) then {
					doStop _u;
					_u setVariable ["vioc_merc_ret", -1];
					if ((_u getVariable ["vioc_merc_role", ""]) in ["sniper", "mg1", "mg2"] && {(_post select 2) > 2.5} && {_bossOk}) then {_u disableAI "PATH"};
				};
			};
		};
	} forEach _all;
	//--- el jefe cambia de lugar de vez en cuando (sin enemigos a la vista)
	if (_bossOk) then {
		if ((_z get "moveEnd") >= 0) then {
			if ((_b distance (_z get "bossAt")) < 1.5 || {time > (_z get "moveEnd")}) then {
				doStop _b;
				_b disableAI "PATH";
				_b setUnitPos "MIDDLE";
				_z set ["moveEnd", -1];
			};
		} else {
			if (time > (_z get "relocAt")) then {
				_z set ["relocAt", time + (VIOC_MERC_RELOC select 0) + random ((VIOC_MERC_RELOC select 1) - (VIOC_MERC_RELOC select 0))];
				if (!_danger && {(behaviour _b) != "COMBAT"} && {random 1 < 0.4}) then {
					private _cands = [];
					{ _cands append ((_x buildingPos -1) select {(_x distance _b) > 4 && {(_x distance2D ((_z get "lair") select 0)) < VIOC_MERC_RELOC_R}}) } forEach (nearestTerrainObjects [getPosATL _b, ["HOUSE", "BUILDING"], VIOC_MERC_RELOC_R, false, true]);
					if (_cands isNotEqualTo []) then {
						private _np = selectRandom _cands;
						_b enableAI "PATH";
						_b setUnitPos "UP";
						_b doMove _np;
						_z set ["bossAt", _np];
						_z set ["moveEnd", time + 90];
						[format ["%1: el jefe cambia de lugar (%2 m)", _z get "name", round (_b distance _np)]] call VIOC_MERC_fnc_log;
					};
				};
			};
		};
	};
	//--- un vehiculo que tomo un jugador deja de ser de la zona (perf_cleanup y el guardado lo tratan como cualquiera)
	{
		private _v = _x;
		if (!isNull _v && {((crew _v) findIf {isPlayer _x}) >= 0}) then {
			_v setVariable ["vioc_merc", nil];
			_v setVariable ["vioc_civ", nil];
			_v setVariable ["VIOC_KEEP", nil];
			_z set ["vobjs", (_z get "vobjs") - [_v]];
		};
	} forEach +(_z get "vobjs");
};

//--- cada 30 s: cuerpos de mercenarios sin jugadores a 300 m
VIOC_MERC_fnc_bodies = {
	{
		_x params ["_u", "_t", "_age"];
		if (!isNull _u && {(time - _t) > _age} && {isNull objectParent _u} && {!([_u, 300] call VIOC_MERC_fnc_nearPlayer)}) then {
			deleteVehicle _u;
			[9] call VIOC_MERC_fnc_stat;
		};
	} forEach +VIOC_MERC_BODIES;
	isNil {VIOC_MERC_BODIES = VIOC_MERC_BODIES select {!isNull (_x select 0)}};
	//--- restos de nuestros vehiculos (cuando la zona ya no los lista) sin jugadores a 300 m
	{
		if (!alive _x && {(_x getVariable ["vioc_merc", ""]) isEqualType ""} && {(_x getVariable ["vioc_merc", ""]) != ""} && {!([_x, 300] call VIOC_MERC_fnc_nearPlayer)}) then {deleteVehicle _x};
	} forEach (allDead select {!(_x isKindOf "CAManBase")});
};

VIOC_MERC_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 60;	//--- towns_capital elige la capital a los 40 s y airfields arma su tabla
	VIOC_MERC_READY = true;
	["listo: " + str [VIOC_MERC_MB, VIOC_MERC_SIDE_A, VIOC_MERC_TOWNS, VIOC_MERC_REWARD, count VIOC_MERC_ARMED, count VIOC_MERC_UNARMED, VIOC_MERC_TOYOTA, count (call VIOC_MERC_fnc_airfields)]] call VIOC_MERC_fnc_log;
	private _n = 0;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		if (_n % 3 == 0) then {call VIOC_MERC_fnc_zonesTick; call VIOC_MERC_fnc_bodies};
		{ [_x] call VIOC_MERC_fnc_zoneTick } forEach +VIOC_MERC_ZONES;
		VIOC_MERC_ZONES = VIOC_MERC_ZONES select {(_x get "state") != "gone"};
		if (VIOC_MERC_MARK) then {call VIOC_MERC_fnc_mkRefresh};
		_n = _n + 1;
		sleep 10;
	};
};

