VIOC_MERC_fnc_info = {
	private _l = [format ["VIOC mercenarios: activo %1 (parametro %2, faccion ION %3), mision B %4, sirven a %5, capital/aerodromos %6, recompensa %7 $",
		VIOC_MERC_ON, VIOC_MERC_MODE, VIOC_MERC_ION, VIOC_MERC_MB, VIOC_MERC_SIDES, VIOC_MERC_TOWNS, VIOC_MERC_REWARD]];
	_l pushBack format ["vehiculos: %1 artillados, %2 de transporte (Toyota: %3)", count VIOC_MERC_ARMED, count VIOC_MERC_UNARMED, count VIOC_MERC_TOYOTA];
	{
		private _z = _x;
		_l pushBack format ["- %1 (%2, %3): %4, %5 hombres, vehiculos %6%7", _z get "name", _z get "kind", _z get "side", _z get "state",
			[count (_z get "roster"), count ([_z] call VIOC_MERC_fnc_units)] select ((_z get "state") != "dormant"),
			(_z get "vehs") apply {_x select 0},
			if (!isNull (_z get "boss") && {alive (_z get "boss")}) then {format [", jefe en %1", mapGridPosition (_z get "boss")]} else {""}];
	} forEach VIOC_MERC_ZONES;
	_l pushBack format ["INFO %1; esperas %2", VIOC_MERC_INFO, (keys VIOC_MERC_CD) apply {[_x, round ((VIOC_MERC_CD get _x) - time)]} select {(_x select 1) > 0}];
	private _t = _l joinString "\n";
	copyToClipboard _t;
	_t
};

VIOC_MERC_fnc_mkRefresh = {
	{ deleteMarkerLocal _x } forEach VIOC_MERC_MKS;
	VIOC_MERC_MKS = [];
	{
		private _z = _x;
		private _m = createMarkerLocal [format ["vioc_merc_z_%1", _forEachIndex], _z get "anchor"];
		_m setMarkerShapeLocal "ELLIPSE";
		_m setMarkerSizeLocal [VIOC_MERC_SPAWN_R, VIOC_MERC_SPAWN_R];
		_m setMarkerBrushLocal "Border";
		_m setMarkerColorLocal (["ColorOrange", "ColorRed"] select ((_z get "state") == "active"));
		VIOC_MERC_MKS pushBack _m;
		private _b = _z get "boss";
		private _bp = if (!isNull _b && {alive _b}) then {getPosATL _b} else {if ((_z get "lair") isNotEqualTo []) then {(_z get "lair") select 0} else {[]}};
		if (_bp isNotEqualTo []) then {
			private _m2 = createMarkerLocal [format ["vioc_merc_b_%1", _forEachIndex], _bp];
			_m2 setMarkerTypeLocal "mil_objective";
			_m2 setMarkerColorLocal "ColorRed";
			_m2 setMarkerTextLocal format ["ION %1 (%2)", _z get "name", _z get "state"];
			VIOC_MERC_MKS pushBack _m2;
		};
	} forEach VIOC_MERC_ZONES;
};

VIOC_MERC_fnc_markers = {
	VIOC_MERC_MARK = !VIOC_MERC_MARK;
	if (VIOC_MERC_MARK) then {call VIOC_MERC_fnc_mkRefresh} else {{ deleteMarkerLocal _x } forEach VIOC_MERC_MKS; VIOC_MERC_MKS = []};
	format ["marcadores de mercenarios: %1", VIOC_MERC_MARK]
};

//--- [jugador] -> texto: contrato de prueba en edificios a 400-900 m delante del jugador (para el bando enemigo del jugador;
//--- el escondite nunca queda a menos de 400 m de un jugador enemigo). Necesita VIOC_MERC activo (el bucle).
VIOC_MERC_fnc_testZone = {
	params [["_pl", objNull]];
	if (isNull _pl) exitWith {"sin jugador"};
	if (!VIOC_MERC_ION) exitWith {"falta la faccion ION de CUP"};
	private _ps = side (group _pl);
	private _side = [east, west] select (_ps == east);
	if (VIOC_MERC_MB && {_ps != east}) then {_side = east};
	if (!VIOC_MERC_ON) exitWith {"mercenarios apagados (parametro VIOC_MERC = No)"};
	private _c = (_pl getPos [600, getDir _pl]) call VIOC_MERC_fnc_p0;
	private _id = format ["test_%1", VIOC_MERC_NEXTID];
	VIOC_MERC_NEXTID = VIOC_MERC_NEXTID + 1;
	private _z = [_side, _id, "test", format ["prueba %1", mapGridPosition _c], objNull, _c] call VIOC_MERC_fnc_newZone;
	private _l = [_z] call VIOC_MERC_fnc_lair;
	if (_l isEqualTo []) exitWith {_z set ["state", "gone"]; "no encontre escondite delante de ti (prueba en otra direccion)"};
	_z set ["lair", _l];
	format ["Zona de prueba %1 para %2: jefe en %3 (a %4 m). Aparece en la proxima pasada (10 s) si no lo ves ni estas a menos de %5 m.",
		_id, _side, mapGridPosition (_l select 0), round (_pl distance2D (_l select 0)), VIOC_MERC_NOSPAWN_R]
};

